      const required = { 'agency.txt': ['agency_name', 'agency_url', 'agency_timezone'], 'stops.txt': ['stop_id', 'stop_name', 'stop_lat', 'stop_lon'], 'routes.txt': ['route_id', 'route_type'], 'trips.txt': ['route_id', 'service_id', 'trip_id'], 'stop_times.txt': ['trip_id', 'arrival_time', 'departure_time', 'stop_id', 'stop_sequence'], 'calendar.txt': ['service_id', 'monday', 'sunday', 'start_date', 'end_date'], 'frequencies.txt': ['trip_id', 'start_time', 'end_time', 'headway_secs'], 'shapes.txt': ['shape_id', 'shape_pt_lat', 'shape_pt_lon', 'shape_pt_sequence'], 'feed_info.txt': ['feed_publisher_name', 'feed_publisher_url', 'feed_lang'] };
