      const svc = new Set(T['calendar.txt'].map((r) => r.service_id)), shapes = new Set(T['shapes.txt'].map((r) => r.shape_id));
      const badStop = T['stop_times.txt'].filter((r) => !stops.has(r.stop_id)).length;
      const badRoute = T['trips.txt'].filter((r) => !routes.has(r.route_id)).length;
      const badSvc = T['trips.txt'].filter((r) => !svc.has(r.service_id)).length;
      const badShape = T['trips.txt'].filter((r) => !shapes.has(r.shape_id)).length;
      const badStTrip = T['stop_times.txt'].filter((r) => !trips.has(r.trip_id)).length;
